      <div class="card-body pit-source-grid"><div v-for="source in readiness" :key="source.source_type" class="pit-source-card"><div class="source-name">{{ sourceLabels[source.source_type] ?? source.source_type }}</div><strong :class="`source-${source.source_status}`">{{ sourceStatusLabels[source.source_status] ?? source.source_status }}</strong><small v-if="source.row_count !== null">{{ source.row_count }} 条</small><small v-if="source.source_ref" class="source-ref">来源：{{ source.source_ref }}</small><el-tooltip v-if="source.issues_json?.length" :content="source.issues_json[0]?.message || '数据存在异常'"><span class="source-issue">查看异常</span></el-tooltip></div></div>
    </section>

    <section v-if="overview?.exists" class="card workflow-card">
      <div class="card-body pit-filter-bar"><el-select v-model="orgFilter" clearable filterable placeholder="全部机构" class="pit-filter-org"><el-option v-for="item in organizationOptions" :key="item" :label="item" :value="item" /></el-select><el-input v-model="keyword" clearable placeholder="搜索机构、姓名、客户或科目" class="pit-filter-keyword" /><el-radio-group v-model="displayMode"><el-radio-button label="all">全部</el-radio-button><el-radio-button label="difference">仅差异</el-radio-button><el-radio-button label="missing">仅缺失</el-radio-button></el-radio-group></div>
      <div class="card-body">
